"use client";

import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import { useParams } from "next/navigation";
import {
  FiActivity, FiArrowLeft, FiAward, FiBookOpen, FiCalendar,
  FiCheckCircle, FiCreditCard, FiDownload, FiEdit3, FiFileText,
  FiMapPin, FiMessageCircle, FiPhone, FiPlus, FiPrinter,
  FiRefreshCw, FiSave, FiShield, FiTrash2, FiUser, FiX,
} from "react-icons/fi";
import { supabase } from "../../../lib/supabase/client";

type Admission = {
  [key: string]: any;
  id: string;
  student_id: string | null;
  student_name: string;
  guardian_name: string | null;
  mobile: string | null;
  course: string | null;
  date_of_birth: string | null;
  message: string | null;
  status: string;
  created_at: string;
  updated_at?: string | null;
  approved_at?: string | null;
  admission_year?: number | null;
  father_name?: string | null;
  mother_name?: string | null;
  guardian_relation?: string | null;
  contact_number_2?: string | null;
  address?: string | null;
  full_address?: string | null;
  village_city?: string | null;
  district?: string | null;
  state?: string | null;
  pin_code?: string | null;
  previous_education?: string | null;
  occupation?: string | null;
  post_office?: string | null;
  country?: string | null;
  student_photo_url?: string | null;
  student_document_type?: string | null;
  student_document_url?: string | null;
};

type Attendance = { id: string; attendance_date: string; status: "present" | "absent" | "leave"; remarks: string | null };
type ExamMark = { id: string; subject: string; max_marks: number; obtained_marks: number; grade: string | null; result_status: "Pass" | "Fail"; remarks: string | null };
type Exam = { id: string; exam_type: "annual" | "common_test"; exam_name: string; exam_date: string | null; session: string | null; remarks: string | null; created_at: string; student_exam_marks: ExamMark[] };
type FeeSetting = { id: string; monthly_fee: number; effective_from: string; active: boolean };
type FeeLedger = { id: string; fee_month: string; amount_due: number; amount_paid: number; payment_date: string | null; payment_method: string | null; receipt_number: string | null; remarks: string | null };
type EditData = { full_name: string; date_of_birth: string; previous_education: string; father_name: string; mother_name: string; guardian_name: string; guardian_relation: string; phone: string; alternate_phone: string; occupation: string; address: string; village: string; post_office: string; district: string; state: string; pincode: string; country: string; course: string };
type ResultRow = { subject: string; max_marks: string; obtained_marks: string; remarks: string };

const emptyResultRow = (): ResultRow => ({ subject: "", max_marks: "100", obtained_marks: "", remarks: "" });
const formatDate = (value: string | null | undefined) => { if (!value) return "—"; const d = new Date(value); return Number.isNaN(d.getTime()) ? "—" : d.toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" }); };
const formatMonth = (value: string) => new Date(`${value}T00:00:00`).toLocaleDateString("en-IN", { month: "long", year: "numeric" });
const money = (value: number | null | undefined) => `₹${Number(value || 0).toLocaleString("en-IN", { minimumFractionDigits: 0, maximumFractionDigits: 2 })}`;
function parseMessage(message: string | null) { const result: Record<string,string> = {}; for (const line of String(message || "").split("\n")) { const i = line.indexOf(":"); if (i > 0) result[line.slice(0,i).trim()] = line.slice(i+1).trim(); } return result; }
function gradeForPercentage(p: number) { if (p >= 90) return "A+"; if (p >= 80) return "A"; if (p >= 70) return "B+"; if (p >= 60) return "B"; if (p >= 50) return "C"; if (p >= 40) return "D"; return "F"; }
function safeText(value: unknown) { return String(value ?? "").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#039;"); }
function openPrintWindow(title: string, body: string) { const popup = window.open("", "_blank", "width=1000,height=800"); if (!popup) return; popup.document.write(`<!doctype html><html><head><title>${safeText(title)}</title><meta name="viewport" content="width=device-width,initial-scale=1"><style>*{box-sizing:border-box}body{margin:0;background:#f3f7f5;color:#0f172a;font-family:Arial,Helvetica,sans-serif;padding:28px}.sheet{max-width:900px;margin:0 auto;background:#fff;border:1px solid #dce7e1;border-radius:18px;padding:32px}.brand{border-bottom:2px solid #0b7a3b;padding-bottom:18px;margin-bottom:22px}.brand h1{margin:0;color:#075c2d;font-size:26px}.brand p{margin:6px 0 0;color:#64748b}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.box{border:1px solid #e2e8f0;border-radius:10px;padding:12px}.label{font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:#64748b;font-weight:700}.value{font-size:14px;font-weight:700;margin-top:5px}.table{width:100%;border-collapse:collapse;margin-top:16px}.table th,.table td{border:1px solid #dbe4df;padding:9px;text-align:left;font-size:12px}.table th{background:#edf8f1;color:#075c2d}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:16px}.summary .box{text-align:center}.signature{display:grid;grid-template-columns:1fr 1fr;gap:80px;margin-top:70px}.signature div{border-top:1px solid #64748b;padding-top:7px;text-align:center;font-size:12px}.idcard{width:700px;max-width:100%;margin:auto;border-radius:22px;overflow:hidden;border:1px solid #b7d8c4}.idtop{background:linear-gradient(135deg,#043b20,#07833e);color:#fff;padding:25px}.idtop h1{margin:0;font-size:24px}.idtop p{margin:6px 0 0;color:#d6f4e0}.idbody{padding:24px;display:grid;grid-template-columns:150px 1fr;gap:24px}.photo{width:150px;height:180px;border-radius:14px;border:3px solid #0b7a3b;object-fit:cover;background:#edf8f1}.photoPlaceholder{width:150px;height:180px;border-radius:14px;background:#edf8f1;color:#0b7a3b;display:flex;align-items:center;justify-content:center;font-size:48px;font-weight:800}.idinfo h2{margin:0;font-size:25px}.idinfo p{margin:8px 0;color:#475569}.badge{display:inline-block;margin-top:6px;padding:5px 10px;border-radius:999px;background:#e6f7ed;color:#08783a;font-size:11px;font-weight:800}.idfooter{background:#f0f8f3;padding:16px 24px;font-size:11px;color:#64748b;display:flex;justify-content:space-between}@media(max-width:650px){body{padding:10px}.sheet{padding:18px}.grid,.summary,.signature,.idbody{grid-template-columns:1fr}.idbody{display:block}.photo,.photoPlaceholder{margin:0 auto 20px}.idcard{width:100%}}@media print{body{background:#fff;padding:0}.sheet{border:0;box-shadow:none;border-radius:0;max-width:none}}</style></head><body><div class="sheet">${body}</div><script>window.onload=function(){setTimeout(function(){window.print()},250)};<\/script></body></html>`); popup.document.close(); }

export default function StudentProfilePage() {
  const params = useParams<{ studentId: string }>();
  const routeId = decodeURIComponent(params.studentId || "");
  const [student,setStudent] = useState<Admission|null>(null);
  const [attendance,setAttendance] = useState<Attendance[]>([]);
  const [exams,setExams] = useState<Exam[]>([]);
  const [feeSettings,setFeeSettings] = useState<FeeSetting[]>([]);
  const [fees,setFees] = useState<FeeLedger[]>([]);
  const [loading,setLoading] = useState(true);
  const [saving,setSaving] = useState(false);
  const [error,setError] = useState("");
  const [notice,setNotice] = useState("");
  const [photoUrl,setPhotoUrl] = useState("");
  const [documentUrl,setDocumentUrl] = useState("");
  const [editing,setEditing] = useState(false);
  const [activeResultType,setActiveResultType] = useState<"annual"|"common_test">("annual");
  const [showResultForm,setShowResultForm] = useState(false);
  const [showAttendanceForm,setShowAttendanceForm] = useState(false);
  const [showFeeForm,setShowFeeForm] = useState(false);
  const [editData,setEditData] = useState<EditData|null>(null);
  const [attendanceForm,setAttendanceForm] = useState({ attendance_date:new Date().toISOString().slice(0,10), status:"present" as Attendance["status"], remarks:"" });
  const [examForm,setExamForm] = useState({ exam_name:"", exam_date:new Date().toISOString().slice(0,10), session:String(new Date().getFullYear()), remarks:"" });
  const [resultRows,setResultRows] = useState<ResultRow[]>([emptyResultRow()]);
  const [monthlyFee,setMonthlyFee] = useState("");
  const [feeEffectiveFrom,setFeeEffectiveFrom] = useState(new Date().toISOString().slice(0,10));
  const [feeForm,setFeeForm] = useState({ feeId:"", amount_paid:"", payment_date:new Date().toISOString().slice(0,10), payment_method:"Cash", remarks:"" });

  const messageData = useMemo(() => parseMessage(student?.message || ""), [student?.message]);

  const loadAll = async () => {
    setLoading(true); setError("");
    try {
      let result = await supabase.from("admissions").select("*").eq("student_id",routeId).maybeSingle();
      if (!result.data && !result.error) result = await supabase.from("admissions").select("*").eq("id",routeId).maybeSingle();
      if (result.error) throw result.error;
      if (!result.data) throw new Error("Student record not found.");
      const admission = result.data as Admission; setStudent(admission);
      const parsed = parseMessage(admission.message);
      setEditData({
        full_name:admission.student_name||"", date_of_birth:admission.date_of_birth||"", previous_education:admission.previous_education||parsed["Previous Education"]||"",
        father_name:admission.father_name||parsed["Father's Name"]||"", mother_name:admission.mother_name||parsed["Mother's Name"]||"", guardian_name:admission.guardian_name||parsed["Guardian Name"]||"",
        guardian_relation:admission.guardian_relation||parsed["Guardian Relationship"]||"", phone:admission.mobile||parsed["Mobile Number 1"]||"", alternate_phone:admission.contact_number_2||parsed["Mobile Number 2"]||"",
        occupation:admission.occupation||parsed["Parent Occupation"]||"", address:admission.full_address||admission.address||parsed["Address"]||"", village:admission.village_city||parsed["Village / Town"]||"",
        post_office:admission.post_office||parsed["Post Office"]||"", district:admission.district||parsed["District"]||"", state:admission.state||parsed["State"]||"", pincode:admission.pin_code||parsed["PIN Code"]||"", country:admission.country||parsed["Country"]||"India", course:admission.course||""
      });
      const [a,e,fs,f] = await Promise.all([
        supabase.from("student_attendance").select("id,attendance_date,status,remarks").eq("admission_id",admission.id).order("attendance_date",{ascending:false}).limit(100),
        supabase.from("student_exams").select("id,exam_type,exam_name,exam_date,session,remarks,created_at,student_exam_marks(id,subject,max_marks,obtained_marks,grade,result_status,remarks)").eq("admission_id",admission.id).order("exam_date",{ascending:false}),
        supabase.from("student_fee_settings").select("id,monthly_fee,effective_from,active").eq("admission_id",admission.id).order("effective_from",{ascending:false}),
        supabase.from("student_fee_ledger").select("id,fee_month,amount_due,amount_paid,payment_date,payment_method,receipt_number,remarks").eq("admission_id",admission.id).order("fee_month",{ascending:false})
      ]);
      if(a.error) throw a.error; if(e.error) throw e.error; if(fs.error) throw fs.error; if(f.error) throw f.error;
      setAttendance((a.data||[]) as Attendance[]); setExams((e.data||[]) as Exam[]); setFeeSettings((fs.data||[]) as FeeSetting[]); setFees((f.data||[]) as FeeLedger[]);
      const photoPath = admission.student_photo_url || parsed["Student Photo"] || ""; const documentPath = admission.student_document_url || parsed["Identity Proof"] || "";
      setPhotoUrl(""); setDocumentUrl("");
      if(photoPath){ const {data} = await supabase.storage.from("admission-documents").createSignedUrl(photoPath,3600); setPhotoUrl(data?.signedUrl||""); }
      if(documentPath){ const {data} = await supabase.storage.from("admission-documents").createSignedUrl(documentPath,3600); setDocumentUrl(data?.signedUrl||""); }
    } catch(err:any) { setError(err?.message||"Unable to load student profile."); } finally { setLoading(false); }
  };
  useEffect(()=>{ loadAll(); },[routeId]);

  const currentFee = feeSettings.find(x=>x.active)?.monthly_fee || 0;
  const paidTotal = fees.reduce((s,x)=>s+Number(x.amount_paid||0),0);
  const dueTotal = fees.reduce((s,x)=>s+Math.max(0,Number(x.amount_due||0)-Number(x.amount_paid||0)),0);
  const presentCount = attendance.filter(x=>x.status==="present").length;
  const absentCount = attendance.filter(x=>x.status==="absent").length;
  const leaveCount = attendance.filter(x=>x.status==="leave").length;
  const attendanceMarked = presentCount+absentCount+leaveCount;
  const attendancePercent = attendanceMarked ? Math.round((presentCount/attendanceMarked)*100) : 0;
  const resultExams = exams.filter(x=>x.exam_type===activeResultType);

  const updateEdit = (key:keyof EditData,value:string)=>setEditData(x=>x?{...x,[key]:value}:x);
  const saveProfile = async () => {
    if(!student||!editData) return; setSaving(true); setNotice("");
    try {
      const p=parseMessage(student.message); const lines=[
        `Application Number: ${p["Application Number"]||""}`,`Father's Name: ${editData.father_name||"Not provided"}`,`Mother's Name: ${editData.mother_name||"Not provided"}`,`Guardian Name: ${editData.guardian_name||"Not provided"}`,`Guardian Relationship: ${editData.guardian_relation||"Not provided"}`,
        `Mobile Number 1: ${editData.phone||"Not provided"}`,`Mobile Number 2: ${editData.alternate_phone||"Not provided"}`,`Parent Occupation: ${editData.occupation||"Not provided"}`,`Previous Education: ${editData.previous_education||"Not provided"}`,`Address: ${editData.address||"Not provided"}`,`Village / Town: ${editData.village||"Not provided"}`,`Post Office: ${editData.post_office||"Not provided"}`,`District: ${editData.district||"Not provided"}`,`State: ${editData.state||"Not provided"}`,`PIN Code: ${editData.pincode||"Not provided"}`,`Country: ${editData.country||"India"}`,
        `Identity Proof Type: ${student.student_document_type||p["Identity Proof Type"]||"Not provided"}`,`Student Photo: ${student.student_photo_url||p["Student Photo"]||""}`,`Identity Proof: ${student.student_document_url||p["Identity Proof"]||""}`
      ].join("\n");
      const {error:updateError}=await supabase.from("admissions").update({student_name:editData.full_name,date_of_birth:editData.date_of_birth||null,previous_education:editData.previous_education||null,father_name:editData.father_name||null,mother_name:editData.mother_name||null,guardian_name:editData.guardian_name||null,guardian_relation:editData.guardian_relation||null,mobile:editData.phone||null,contact_number_2:editData.alternate_phone||null,occupation:editData.occupation||null,full_address:editData.address||null,address:editData.address||null,village_city:editData.village||null,post_office:editData.post_office||null,district:editData.district||null,state:editData.state||null,pin_code:editData.pincode||null,country:editData.country||null,course:editData.course||null,message:lines}).eq("id",student.id);
      if(updateError) throw updateError; setEditing(false); setNotice("Student profile updated successfully."); await loadAll();
    } catch(err:any){setError(err?.message||"Unable to update student profile.");} finally{setSaving(false);}
  };

  const addAttendance = async () => {
    if(!student) return; setSaving(true); try{ const {error:e}=await supabase.from("student_attendance").upsert({admission_id:student.id,attendance_date:attendanceForm.attendance_date,status:attendanceForm.status,remarks:attendanceForm.remarks||null},{onConflict:"admission_id,attendance_date"}); if(e)throw e; setNotice("Attendance saved."); setShowAttendanceForm(false); await loadAll(); }catch(err:any){setError(err?.message||"Unable to save attendance.");}finally{setSaving(false);}
  };
  const deleteAttendance = async(id:string)=>{if(!confirm("Delete this attendance entry?"))return;const{error:e}=await supabase.from("student_attendance").delete().eq("id",id);if(e)setError(e.message);else await loadAll();};
  const updateResultRow=(i:number,key:keyof ResultRow,value:string)=>setResultRows(rows=>rows.map((r,index)=>index===i?{...r,[key]:value}:r));
  const saveExam = async () => {
    if(!student)return; const rows=resultRows.filter(x=>x.subject.trim()&&Number(x.max_marks)>0); if(!examForm.exam_name.trim()||!rows.length){setError("Exam name aur kam se kam ek subject/result required hai.");return;} setSaving(true);
    try{const{data:exam,error:e}=await supabase.from("student_exams").insert({admission_id:student.id,exam_type:activeResultType,exam_name:examForm.exam_name.trim(),exam_date:examForm.exam_date||null,session:examForm.session||null,remarks:examForm.remarks||null}).select("id").single();if(e)throw e;const marks=rows.map(r=>{const max=Number(r.max_marks),obt=Math.min(max,Math.max(0,Number(r.obtained_marks||0))),p=max?(obt/max)*100:0;return{exam_id:exam.id,subject:r.subject.trim(),max_marks:max,obtained_marks:obt,grade:gradeForPercentage(p),result_status:p>=40?"Pass":"Fail",remarks:r.remarks||null};});const{error:me}=await supabase.from("student_exam_marks").insert(marks);if(me)throw me;setNotice("Result saved successfully.");setShowResultForm(false);setResultRows([emptyResultRow()]);setExamForm({exam_name:"",exam_date:new Date().toISOString().slice(0,10),session:String(new Date().getFullYear()),remarks:""});await loadAll();}catch(err:any){setError(err?.message||"Unable to save result.");}finally{setSaving(false);}
  };
  const deleteExam=async(id:string)=>{if(!confirm("Delete this complete result?"))return;const{error:e}=await supabase.from("student_exams").delete().eq("id",id);if(e)setError(e.message);else await loadAll();};
  const printResult=(exam:Exam)=>{if(!student)return;const max=exam.student_exam_marks.reduce((s,m)=>s+Number(m.max_marks),0),got=exam.student_exam_marks.reduce((s,m)=>s+Number(m.obtained_marks),0),pct=max?(got/max)*100:0,pass=exam.student_exam_marks.every(m=>m.result_status==="Pass");const rows=exam.student_exam_marks.map(m=>`<tr><td>${safeText(m.subject)}</td><td>${m.max_marks}</td><td>${m.obtained_marks}</td><td>${((Number(m.obtained_marks)/Number(m.max_marks))*100).toFixed(1)}%</td><td>${safeText(m.grade||gradeForPercentage((Number(m.obtained_marks)/Number(m.max_marks))*100))}</td><td>${m.result_status}</td><td>${safeText(m.remarks||"—")}</td></tr>`).join("");openPrintWindow(`${exam.exam_name} Result`, `<div class="brand"><h1>Madrasa Majmaul Bahrain Bijol</h1><p>Official Student Result</p></div><div class="grid"><div class="box"><div class="label">Student Name</div><div class="value">${safeText(student.student_name)}</div></div><div class="box"><div class="label">Student ID</div><div class="value">${safeText(student.student_id)}</div></div><div class="box"><div class="label">Examination</div><div class="value">${safeText(exam.exam_name)}</div></div><div class="box"><div class="label">Type / Session</div><div class="value">${exam.exam_type==="annual"?"Annual Examination":"Common Test"} / ${safeText(exam.session||"—")}</div></div><div class="box"><div class="label">Exam Date</div><div class="value">${formatDate(exam.exam_date)}</div></div><div class="box"><div class="label">Final Result</div><div class="value">${pass?"PASS":"FAIL"}</div></div></div><table class="table"><thead><tr><th>Subject</th><th>Max</th><th>Obtained</th><th>%</th><th>Grade</th><th>Result</th><th>Remarks</th></tr></thead><tbody>${rows}</tbody></table><div class="summary"><div class="box"><div class="label">Total Marks</div><div class="value">${max}</div></div><div class="box"><div class="label">Obtained</div><div class="value">${got}</div></div><div class="box"><div class="label">Percentage</div><div class="value">${pct.toFixed(2)}%</div></div><div class="box"><div class="label">Grade</div><div class="value">${gradeForPercentage(pct)}</div></div></div><p style="margin-top:20px;color:#475569"><strong>Remarks:</strong> ${safeText(exam.remarks||"—")}</p><div class="signature"><div>Class / Subject Teacher</div><div>Principal / Authorized Signatory</div></div>`);};

  const saveMonthlyFee=async()=>{if(!student||!monthlyFee)return;const amount=Number(monthlyFee);if(!Number.isFinite(amount)||amount<0){setError("Valid monthly fee enter karein.");return;}setSaving(true);try{await supabase.from("student_fee_settings").update({active:false}).eq("admission_id",student.id);const{error:e}=await supabase.from("student_fee_settings").insert({admission_id:student.id,monthly_fee:amount,effective_from:feeEffectiveFrom,active:true});if(e)throw e;const{error:rpc}=await supabase.rpc("ensure_student_fee_ledger",{p_admission_id:student.id});if(rpc)throw rpc;setMonthlyFee("");setShowFeeForm(false);setNotice("Monthly fee set and monthly ledger updated.");await loadAll();}catch(err:any){setError(err?.message||"Unable to set monthly fee.");}finally{setSaving(false);}};
  const recordFeePayment=async(fee:FeeLedger)=>{const amount=Number(feeForm.amount_paid);if(!Number.isFinite(amount)||amount<=0){setError("Payment amount enter karein.");return;}if(amount>Number(fee.amount_due)-Number(fee.amount_paid)){setError("Payment outstanding amount se zyada nahi ho sakta.");return;}setSaving(true);try{const receipt=fee.receipt_number||`MMBB-FEE-${new Date().getFullYear()}-${Date.now().toString().slice(-7)}`;const{error:e}=await supabase.from("student_fee_ledger").update({amount_paid:Number(fee.amount_paid)+amount,payment_date:feeForm.payment_date,payment_method:feeForm.payment_method,receipt_number:receipt,remarks:feeForm.remarks||fee.remarks||null}).eq("id",fee.id);if(e)throw e;setFeeForm({feeId:"",amount_paid:"",payment_date:new Date().toISOString().slice(0,10),payment_method:"Cash",remarks:""});setNotice("Fee payment recorded.");await loadAll();}catch(err:any){setError(err?.message||"Unable to record fee payment.");}finally{setSaving(false);}};
  const printReceipt=(fee:FeeLedger)=>{if(!student)return;openPrintWindow(`Fee Receipt ${fee.receipt_number||""}`, `<div class="brand"><h1>Madrasa Majmaul Bahrain Bijol</h1><p>Official Fee Receipt</p></div><div class="grid"><div class="box"><div class="label">Receipt Number</div><div class="value">${safeText(fee.receipt_number||"—")}</div></div><div class="box"><div class="label">Payment Date</div><div class="value">${formatDate(fee.payment_date)}</div></div><div class="box"><div class="label">Student Name</div><div class="value">${safeText(student.student_name)}</div></div><div class="box"><div class="label">Student ID</div><div class="value">${safeText(student.student_id)}</div></div><div class="box"><div class="label">Fee Month</div><div class="value">${formatMonth(fee.fee_month)}</div></div><div class="box"><div class="label">Payment Method</div><div class="value">${safeText(fee.payment_method||"—")}</div></div></div><table class="table"><thead><tr><th>Description</th><th>Amount</th></tr></thead><tbody><tr><td>Monthly Madrasa Fee</td><td>${money(fee.amount_paid)}</td></tr></tbody></table><div class="summary"><div class="box"><div class="label">Monthly Due</div><div class="value">${money(fee.amount_due)}</div></div><div class="box"><div class="label">Paid</div><div class="value">${money(fee.amount_paid)}</div></div><div class="box"><div class="label">Balance</div><div class="value">${money(Math.max(0,Number(fee.amount_due)-Number(fee.amount_paid)))}</div></div><div class="box"><div class="label">Status</div><div class="value">${Number(fee.amount_paid)>=Number(fee.amount_due)?"PAID":"PARTIAL"}</div></div></div><p style="margin-top:20px;color:#475569"><strong>Remarks:</strong> ${safeText(fee.remarks||"—")}</p><div class="signature"><div>Received By</div><div>Authorized Signatory</div></div>`);};
  const printIdCard=()=>{if(!student)return;const initials=student.student_name.split(/\s+/).map(x=>x[0]).slice(0,2).join("").toUpperCase();const photo=photoUrl?`<img class="photo" src="${safeText(photoUrl)}" alt="Student Photo">`:`<div class="photoPlaceholder">${safeText(initials)}</div>`;openPrintWindow(`Student ID Card - ${student.student_name}`, `<div class="idcard"><div class="idtop"><h1>Madrasa Majmaul Bahrain Bijol</h1><p>Official Student Identity Card</p></div><div class="idbody">${photo}<div class="idinfo"><h2>${safeText(student.student_name)}</h2><p><strong>Student ID:</strong> ${safeText(student.student_id)}</p><p><strong>Course:</strong> ${safeText(student.course||"—")}</p><p><strong>Date of Birth:</strong> ${formatDate(student.date_of_birth)}</p><span class="badge">APPROVED STUDENT</span></div></div><div class="idfooter"><span>Issued by Madrasa Administration</span><span>${new Date().getFullYear()}</span></div></div>`);};

  if(loading)return <main className="min-h-screen bg-slate-50 flex items-center justify-center"><div className="text-center"><div className="mx-auto h-12 w-12 animate-spin rounded-full border-4 border-slate-200 border-t-green-700"/><p className="mt-4 font-bold text-slate-700">Loading student profile...</p></div></main>;
  if(!student)return <main className="min-h-screen bg-slate-50 p-6"><div className="mx-auto mt-20 max-w-xl rounded-3xl bg-white p-10 text-center shadow-xl"><FiUser className="mx-auto text-5xl text-red-500"/><h1 className="mt-4 text-2xl font-extrabold">Student not found</h1><p className="mt-2 text-slate-500">{error||"The requested student record could not be found."}</p><Link href="/admin/students" className="mt-6 inline-flex rounded-xl bg-green-700 px-5 py-3 font-bold text-white">Back to Students</Link></div></main>;
  const initials=student.student_name.split(/\s+/).map(x=>x[0]).slice(0,2).join("").toUpperCase();

  return <main className="min-h-screen bg-[#f4f7f5] text-slate-900">
    <header className="sticky top-0 z-40 border-b border-slate-200/80 bg-white/95 backdrop-blur-xl"><div className="mx-auto flex max-w-[1500px] items-center justify-between gap-4 px-4 py-3 sm:px-6 lg:px-8"><Link href="/admin/students" className="inline-flex items-center gap-2 rounded-xl px-3 py-2 text-sm font-bold text-slate-600 hover:bg-slate-100"><FiArrowLeft/> Students</Link><div className="hidden text-center sm:block"><p className="text-[10px] font-black uppercase tracking-[0.3em] text-green-700">Madrasa Majmaul Bahrain Bijol</p><p className="text-sm font-extrabold text-slate-800">Student Profile</p></div><div className="flex items-center gap-2"><button onClick={loadAll} className="rounded-xl border border-slate-200 bg-white p-2.5 text-slate-600 hover:bg-slate-50"><FiRefreshCw/></button><button onClick={()=>setEditing(v=>!v)} className="inline-flex items-center gap-2 rounded-xl bg-slate-900 px-3 py-2.5 text-sm font-bold text-white hover:bg-slate-800"><FiEdit3/><span className="hidden sm:inline">Edit</span></button></div></div></header>
    <section className="mx-auto max-w-[1500px] px-4 py-6 sm:px-6 lg:px-8 lg:py-8">
      {error&&<div className="mb-5 flex items-start justify-between gap-4 rounded-2xl border border-red-200 bg-red-50 p-4 text-red-700"><div><p className="font-bold">Action failed</p><p className="text-sm">{error}</p></div><button onClick={()=>setError("")}><FiX/></button></div>}
      {notice&&<div className="mb-5 flex items-center justify-between gap-4 rounded-2xl border border-green-200 bg-green-50 p-4 text-green-800"><p className="font-bold">✓ {notice}</p><button onClick={()=>setNotice("")}><FiX/></button></div>}
      <div className="overflow-hidden rounded-[30px] bg-gradient-to-br from-[#063b20] via-[#08743a] to-[#0ba24e] text-white shadow-[0_25px_70px_-30px_rgba(0,80,40,.55)]"><div className="p-6 sm:p-8 lg:p-10"><div className="flex flex-col gap-7 lg:flex-row lg:items-center lg:justify-between"><div className="flex items-center gap-5 sm:gap-7">{photoUrl?<img src={photoUrl} alt="Student" className="h-24 w-24 rounded-3xl border-4 border-white/25 object-cover shadow-xl sm:h-32 sm:w-32"/>:<div className="flex h-24 w-24 items-center justify-center rounded-3xl border border-white/20 bg-white/10 text-3xl font-black sm:h-32 sm:w-32 sm:text-4xl">{initials}</div>}<div className="min-w-0"><p className="text-xs font-black uppercase tracking-[0.28em] text-green-100">Approved Student</p><h1 className="mt-2 break-words text-3xl font-black tracking-tight sm:text-4xl lg:text-5xl">{student.student_name}</h1><div className="mt-3 flex flex-wrap items-center gap-2"><span className="rounded-full bg-white/15 px-3 py-1.5 text-xs font-black tracking-wide">{student.student_id||"ID pending"}</span><span className="rounded-full bg-white px-3 py-1.5 text-xs font-black text-green-800">✓ APPROVED</span></div><p className="mt-3 text-sm text-green-50">{student.course||"Course not specified"}</p></div></div><div className="flex flex-wrap gap-2.5"><button onClick={printIdCard} className="inline-flex items-center gap-2 rounded-xl bg-white px-4 py-3 text-sm font-black text-green-800 shadow-lg hover:bg-green-50"><FiCreditCard/> ID Card</button><button onClick={()=>window.print()} className="inline-flex items-center gap-2 rounded-xl border border-white/25 bg-white/10 px-4 py-3 text-sm font-black text-white hover:bg-white/15"><FiPrinter/> Print Profile</button>{student.mobile&&<a href={`tel:${student.mobile}`} className="inline-flex items-center gap-2 rounded-xl bg-blue-500 px-4 py-3 text-sm font-black text-white hover:bg-blue-600"><FiPhone/> Call</a>}{student.mobile&&<a target="_blank" rel="noreferrer" href={`https://wa.me/${student.mobile.replace(/\D/g,"")}`} className="inline-flex items-center gap-2 rounded-xl bg-white/10 px-4 py-3 text-sm font-black text-white hover:bg-white/15"><FiMessageCircle/> WhatsApp</a>}</div></div></div><div className="grid border-t border-white/10 bg-black/10 sm:grid-cols-3"><div className="p-5"><p className="text-[10px] font-black uppercase tracking-wider text-green-100">Admission Year</p><p className="mt-1 text-lg font-extrabold">{student.admission_year||new Date(student.created_at).getFullYear()}</p></div><div className="border-white/10 p-5 sm:border-l"><p className="text-[10px] font-black uppercase tracking-wider text-green-100">Admission Date</p><p className="mt-1 text-lg font-extrabold">{formatDate(student.approved_at||student.created_at)}</p></div><div className="border-white/10 p-5 sm:border-l"><p className="text-[10px] font-black uppercase tracking-wider text-green-100">Status</p><p className="mt-1 text-lg font-extrabold">Active / Approved</p></div></div></div>

      {editing&&editData&&<section className="mt-6 rounded-3xl border border-slate-200 bg-white p-5 shadow-sm sm:p-7"><div className="flex items-center justify-between"><div><p className="text-xs font-black uppercase tracking-[0.22em] text-green-700">Profile Management</p><h2 className="mt-1 text-2xl font-black">Edit Admission Details</h2><p className="mt-1 text-sm text-slate-500">Sirf wahi fields jo admission form mein hain.</p></div><button onClick={()=>setEditing(false)} className="rounded-xl p-2 hover:bg-slate-100"><FiX/></button></div><div className="mt-6 grid gap-4 md:grid-cols-2 lg:grid-cols-3">{([ ["full_name","Student Name"],["date_of_birth","Date of Birth"],["previous_education","Previous Education"],["father_name","Father's Name"],["mother_name","Mother's Name"],["guardian_name","Guardian Name"],["guardian_relation","Relationship"],["phone","Mobile Number 1"],["alternate_phone","Mobile Number 2"],["occupation","Parent Occupation"],["address","Full Address"],["village","Village / Town"],["post_office","Post Office"],["district","District"],["state","State"],["pincode","PIN Code"],["country","Country"],["course","Course"] ] as [keyof EditData,string][]).map(([key,label])=><label key={key} className="text-sm font-bold text-slate-700">{label}<input type={key==="date_of_birth"?"date":"text"} value={editData[key]} onChange={e=>updateEdit(key,e.target.value)} className="mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 px-3.5 py-3 outline-none focus:border-green-600 focus:bg-white focus:ring-2 focus:ring-green-100"/></label>)}</div><div className="mt-6 flex justify-end gap-3"><button onClick={()=>setEditing(false)} className="rounded-xl border border-slate-200 px-5 py-3 font-bold text-slate-700">Cancel</button><button disabled={saving} onClick={saveProfile} className="inline-flex items-center gap-2 rounded-xl bg-green-700 px-5 py-3 font-black text-white disabled:opacity-60"><FiSave/>{saving?"Saving...":"Save Changes"}</button></div></section>}

      <div className="mt-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard icon={<FiCalendar/>} label="Date of Birth" value={formatDate(student.date_of_birth)}/><StatCard icon={<FiBookOpen/>} label="Course" value={student.course||"—"}/><StatCard icon={<FiActivity/>} label="Attendance" value={attendanceMarked?`${attendancePercent}%`:"Not marked"}/><StatCard icon={<FiCreditCard/>} label="Fee Balance" value={money(dueTotal)}/></div>

      <div className="mt-8 space-y-6">
        <ProfileSection title="Basic Information" icon={<FiUser/>}><InfoGrid items={[["Student Full Name",student.student_name],["Date of Birth",formatDate(student.date_of_birth)],["Previous Education",student.previous_education||messageData["Previous Education"]||"—"]]}/></ProfileSection>
        <ProfileSection title="Parent / Guardian Information" icon={<FiShield/>}><InfoGrid items={[["Father's Name",student.father_name||messageData["Father's Name"]||"—"],["Mother's Name",student.mother_name||messageData["Mother's Name"]||"—"],["Guardian Name",student.guardian_name||messageData["Guardian Name"]||"—"],["Relationship",student.guardian_relation||messageData["Guardian Relationship"]||"—"],["Mobile Number 1",student.mobile||messageData["Mobile Number 1"]||"—"],["Mobile Number 2",student.contact_number_2||messageData["Mobile Number 2"]||"—"],["Parent Occupation",student.occupation||messageData["Parent Occupation"]||"—"]]}/></ProfileSection>
        <ProfileSection title="Address Information" icon={<FiMapPin/>}><InfoGrid items={[["Full Address",student.full_address||student.address||messageData["Address"]||"—"],["Village / Town",student.village_city||messageData["Village / Town"]||"—"],["Post Office",student.post_office||messageData["Post Office"]||"—"],["District",student.district||messageData["District"]||"—"],["State",student.state||messageData["State"]||"—"],["PIN Code",student.pin_code||messageData["PIN Code"]||"—"],["Country",student.country||messageData["Country"]||"India"]]}/></ProfileSection>
        <ProfileSection title="Course" icon={<FiBookOpen/>}><div className="rounded-2xl border border-green-100 bg-green-50 p-5"><p className="text-xs font-black uppercase tracking-wider text-green-700">Current Course</p><p className="mt-2 text-2xl font-black text-green-950">{student.course||"Not specified"}</p></div></ProfileSection>

        <ProfileSection title="Attendance" icon={<FiCheckCircle/>} action={<button onClick={()=>setShowAttendanceForm(v=>!v)} className="inline-flex items-center gap-2 rounded-xl bg-green-700 px-4 py-2.5 text-sm font-black text-white"><FiPlus/> Mark Attendance</button>}><div className="grid gap-3 sm:grid-cols-3"><MiniStat label="Present" value={presentCount} tone="green"/><MiniStat label="Absent" value={absentCount} tone="red"/><MiniStat label="Leave" value={leaveCount} tone="amber"/></div>{showAttendanceForm&&<div className="mt-5 rounded-2xl border border-slate-200 bg-slate-50 p-4"><div className="grid gap-4 md:grid-cols-3"><label className="text-sm font-bold">Date<input type="date" value={attendanceForm.attendance_date} onChange={e=>setAttendanceForm({...attendanceForm,attendance_date:e.target.value})} className="mt-2 w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5"/></label><label className="text-sm font-bold">Status<select value={attendanceForm.status} onChange={e=>setAttendanceForm({...attendanceForm,status:e.target.value as Attendance["status"]})} className="mt-2 w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5"><option value="present">Present</option><option value="absent">Absent</option><option value="leave">Leave</option></select></label><label className="text-sm font-bold">Remarks<input value={attendanceForm.remarks} onChange={e=>setAttendanceForm({...attendanceForm,remarks:e.target.value})} className="mt-2 w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5"/></label></div><button disabled={saving} onClick={addAttendance} className="mt-4 rounded-xl bg-slate-900 px-4 py-2.5 text-sm font-black text-white">{saving?"Saving...":"Save Attendance"}</button></div>}<div className="mt-5 overflow-x-auto"><table className="w-full min-w-[650px] text-left text-sm"><thead><tr className="border-b border-slate-200 text-xs uppercase tracking-wider text-slate-500"><th className="px-3 py-3">Date</th><th>Status</th><th>Remarks</th><th className="text-right">Action</th></tr></thead><tbody>{attendance.slice(0,15).map(item=><tr key={item.id} className="border-b border-slate-100"><td className="px-3 py-3 font-bold">{formatDate(item.attendance_date)}</td><td><span className={`rounded-full px-2.5 py-1 text-xs font-black ${item.status==="present"?"bg-green-100 text-green-700":item.status==="absent"?"bg-red-100 text-red-700":"bg-amber-100 text-amber-700"}`}>{item.status.toUpperCase()}</span></td><td>{item.remarks||"—"}</td><td className="text-right"><button onClick={()=>deleteAttendance(item.id)} className="rounded-lg p-2 text-red-500 hover:bg-red-50"><FiTrash2/></button></td></tr>)}</tbody></table>{attendance.length===0&&<p className="py-8 text-center text-sm text-slate-500">Attendance abhi record nahi hui.</p>}</div></ProfileSection>

        <ProfileSection title="Examination & Results" icon={<FiAward/>} action={<button onClick={()=>setShowResultForm(v=>!v)} className="inline-flex items-center gap-2 rounded-xl bg-green-700 px-4 py-2.5 text-sm font-black text-white"><FiPlus/> Add Result</button>}><div className="flex flex-wrap gap-2 rounded-2xl bg-slate-100 p-1.5"><button onClick={()=>setActiveResultType("annual")} className={`rounded-xl px-4 py-2.5 text-sm font-black ${activeResultType==="annual"?"bg-white text-green-700 shadow-sm":"text-slate-500"}`}>Annual Examination</button><button onClick={()=>setActiveResultType("common_test")} className={`rounded-xl px-4 py-2.5 text-sm font-black ${activeResultType==="common_test"?"bg-white text-green-700 shadow-sm":"text-slate-500"}`}>Common Test</button></div>{showResultForm&&<div className="mt-5 rounded-2xl border border-green-100 bg-green-50/60 p-5"><div className="grid gap-4 md:grid-cols-3"><label className="text-sm font-bold">Exam Name<input value={examForm.exam_name} onChange={e=>setExamForm({...examForm,exam_name:e.target.value})} placeholder={activeResultType==="annual"?"Annual Examination 2026":"Common Test - 01"} className="mt-2 w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5"/></label><label className="text-sm font-bold">Exam Date<input type="date" value={examForm.exam_date} onChange={e=>setExamForm({...examForm,exam_date:e.target.value})} className="mt-2 w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5"/></label><label className="text-sm font-bold">Session<input value={examForm.session} onChange={e=>setExamForm({...examForm,session:e.target.value})} className="mt-2 w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5"/></label></div><div className="mt-5 space-y-3">{resultRows.map((row,index)=><div key={index} className="grid gap-3 rounded-xl border border-slate-200 bg-white p-3 md:grid-cols-[1.5fr_.7fr_.7fr_1fr_auto]"><input placeholder="Subject" value={row.subject} onChange={e=>updateResultRow(index,"subject",e.target.value)} className="rounded-lg border border-slate-200 px-3 py-2"/><input type="number" min="1" placeholder="Max Marks" value={row.max_marks} onChange={e=>updateResultRow(index,"max_marks",e.target.value)} className="rounded-lg border border-slate-200 px-3 py-2"/><input type="number" min="0" placeholder="Obtained" value={row.obtained_marks} onChange={e=>updateResultRow(index,"obtained_marks",e.target.value)} className="rounded-lg border border-slate-200 px-3 py-2"/><input placeholder="Remarks" value={row.remarks} onChange={e=>updateResultRow(index,"remarks",e.target.value)} className="rounded-lg border border-slate-200 px-3 py-2"/><button onClick={()=>setResultRows(rows=>rows.length===1?rows:rows.filter((_,i)=>i!==index))} className="rounded-lg p-2 text-red-500 hover:bg-red-50"><FiTrash2/></button></div>)}</div><div className="mt-4 flex flex-wrap gap-3"><button onClick={()=>setResultRows(rows=>[...rows,emptyResultRow()])} className="inline-flex items-center gap-2 rounded-xl border border-green-200 bg-white px-4 py-2.5 text-sm font-black text-green-700"><FiPlus/> Add Subject</button><button disabled={saving} onClick={saveExam} className="inline-flex items-center gap-2 rounded-xl bg-green-700 px-4 py-2.5 text-sm font-black text-white">{saving?"Saving...":"Save Complete Result"}</button></div></div>}<div className="mt-5 space-y-4">{resultExams.map(exam=>{const max=exam.student_exam_marks.reduce((s,m)=>s+Number(m.max_marks),0),got=exam.student_exam_marks.reduce((s,m)=>s+Number(m.obtained_marks),0),pct=max?(got/max)*100:0,pass=exam.student_exam_marks.every(m=>m.result_status==="Pass");return <div key={exam.id} className="overflow-hidden rounded-2xl border border-slate-200 bg-white"><div className="flex flex-col gap-3 border-b border-slate-100 bg-slate-50 p-5 sm:flex-row sm:items-center sm:justify-between"><div><div className="flex flex-wrap items-center gap-2"><span className="rounded-full bg-green-100 px-2.5 py-1 text-xs font-black text-green-700">{activeResultType==="annual"?"ANNUAL":"COMMON TEST"}</span><span className={`rounded-full px-2.5 py-1 text-xs font-black ${pass?"bg-emerald-100 text-emerald-700":"bg-red-100 text-red-700"}`}>{pass?"PASS":"FAIL"}</span></div><h3 className="mt-2 text-xl font-black">{exam.exam_name}</h3><p className="mt-1 text-sm text-slate-500">{formatDate(exam.exam_date)} · Session {exam.session||"—"}</p></div><div className="flex flex-wrap gap-2"><button onClick={()=>printResult(exam)} className="inline-flex items-center gap-2 rounded-xl bg-slate-900 px-3 py-2.5 text-sm font-black text-white"><FiPrinter/> Print Result</button><button onClick={()=>deleteExam(exam.id)} className="rounded-xl border border-red-200 p-2.5 text-red-600"><FiTrash2/></button></div></div><div className="overflow-x-auto"><table className="w-full min-w-[700px] text-left text-sm"><thead><tr className="border-b border-slate-100 text-xs uppercase text-slate-500"><th className="p-4">Subject</th><th>Max</th><th>Obtained</th><th>%</th><th>Grade</th><th>Result</th><th>Remarks</th></tr></thead><tbody>{exam.student_exam_marks.map(m=><tr key={m.id} className="border-b border-slate-50"><td className="p-4 font-bold">{m.subject}</td><td>{m.max_marks}</td><td>{m.obtained_marks}</td><td>{((Number(m.obtained_marks)/Number(m.max_marks))*100).toFixed(1)}%</td><td className="font-black">{m.grade||gradeForPercentage((Number(m.obtained_marks)/Number(m.max_marks))*100)}</td><td><span className={`rounded-full px-2 py-1 text-xs font-black ${m.result_status==="Pass"?"bg-green-100 text-green-700":"bg-red-100 text-red-700"}`}>{m.result_status}</span></td><td>{m.remarks||"—"}</td></tr>)}</tbody></table></div><div className="grid border-t border-slate-100 bg-green-50/50 sm:grid-cols-4"><div className="p-4"><p className="text-xs text-slate-500">Total</p><p className="font-black">{max}</p></div><div className="p-4"><p className="text-xs text-slate-500">Obtained</p><p className="font-black">{got}</p></div><div className="p-4"><p className="text-xs text-slate-500">Percentage</p><p className="font-black">{pct.toFixed(2)}%</p></div><div className="p-4"><p className="text-xs text-slate-500">Grade</p><p className="font-black">{gradeForPercentage(pct)}</p></div></div></div>})}{resultExams.length===0&&<div className="rounded-2xl border border-dashed border-slate-300 p-10 text-center"><FiAward className="mx-auto text-4xl text-slate-300"/><p className="mt-3 font-bold text-slate-500">Is category ka result abhi nahi hai.</p></div>}</div></ProfileSection>

        <ProfileSection title="Fees & Monthly Ledger" icon={<FiCreditCard/>} action={<button onClick={()=>setShowFeeForm(v=>!v)} className="inline-flex items-center gap-2 rounded-xl bg-green-700 px-4 py-2.5 text-sm font-black text-white"><FiPlus/> Set Monthly Fee</button>}><div className="grid gap-3 sm:grid-cols-3"><MiniStat label="Monthly Fee" value={money(currentFee)} tone="green"/><MiniStat label="Total Paid" value={money(paidTotal)} tone="blue"/><MiniStat label="Outstanding" value={money(dueTotal)} tone="red"/></div>{showFeeForm&&<div className="mt-5 rounded-2xl border border-green-100 bg-green-50/60 p-5"><div className="grid gap-4 md:grid-cols-2"><label className="text-sm font-bold">Monthly Fee<input type="number" min="0" value={monthlyFee} onChange={e=>setMonthlyFee(e.target.value)} placeholder="700" className="mt-2 w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5"/></label><label className="text-sm font-bold">Effective From<input type="date" value={feeEffectiveFrom} onChange={e=>setFeeEffectiveFrom(e.target.value)} className="mt-2 w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5"/></label></div><p className="mt-3 text-xs text-slate-500">Ek baar monthly fee set karne ke baad har month ki ledger entry isi fee ke hisab se generate hogi.</p><button disabled={saving} onClick={saveMonthlyFee} className="mt-4 rounded-xl bg-green-700 px-4 py-2.5 text-sm font-black text-white">{saving?"Saving...":"Save Monthly Fee"}</button></div>}<div className="mt-5 overflow-x-auto"><table className="w-full min-w-[950px] text-left text-sm"><thead><tr className="border-b border-slate-200 text-xs uppercase tracking-wider text-slate-500"><th className="p-3">Month</th><th>Due</th><th>Paid</th><th>Balance</th><th>Payment Date</th><th>Method</th><th>Receipt</th><th>Action</th></tr></thead><tbody>{fees.map(fee=>{const balance=Math.max(0,Number(fee.amount_due)-Number(fee.amount_paid));return <tr key={fee.id} className="border-b border-slate-100"><td className="p-3 font-bold">{formatMonth(fee.fee_month)}</td><td>{money(fee.amount_due)}</td><td className="font-bold text-green-700">{money(fee.amount_paid)}</td><td className={`font-bold ${balance?"text-red-600":"text-green-700"}`}>{money(balance)}</td><td>{formatDate(fee.payment_date)}</td><td>{fee.payment_method||"—"}</td><td>{fee.receipt_number||"—"}</td><td><div className="flex gap-2">{balance>0&&<button onClick={()=>setFeeForm({feeId:fee.id,amount_paid:String(balance),payment_date:new Date().toISOString().slice(0,10),payment_method:fee.payment_method||"Cash",remarks:fee.remarks||""})} className="rounded-lg bg-green-700 px-3 py-2 text-xs font-black text-white">Record</button>}{fee.amount_paid>0&&<button onClick={()=>printReceipt(fee)} className="rounded-lg border border-slate-200 p-2 text-slate-700"><FiPrinter/></button>}</div></td></tr>})}</tbody></table>{fees.length===0&&<p className="py-10 text-center text-sm text-slate-500">Monthly fee set karne ke baad ledger yahan automatically generate hoga.</p>}</div>{feeForm.feeId&&<div className="mt-5 rounded-2xl border border-slate-200 bg-slate-50 p-5"><div className="grid gap-4 md:grid-cols-4"><label className="text-sm font-bold">Payment Amount<input type="number" min="0" value={feeForm.amount_paid} onChange={e=>setFeeForm({...feeForm,amount_paid:e.target.value})} className="mt-2 w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5"/></label><label className="text-sm font-bold">Payment Date<input type="date" value={feeForm.payment_date} onChange={e=>setFeeForm({...feeForm,payment_date:e.target.value})} className="mt-2 w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5"/></label><label className="text-sm font-bold">Method<select value={feeForm.payment_method} onChange={e=>setFeeForm({...feeForm,payment_method:e.target.value})} className="mt-2 w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5"><option>Cash</option><option>UPI</option><option>Bank Transfer</option><option>Other</option></select></label><label className="text-sm font-bold">Remarks<input value={feeForm.remarks} onChange={e=>setFeeForm({...feeForm,remarks:e.target.value})} className="mt-2 w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5"/></label></div><div className="mt-4 flex gap-2"><button disabled={saving} onClick={()=>{const fee=fees.find(x=>x.id===feeForm.feeId);if(fee)recordFeePayment(fee)}} className="rounded-xl bg-green-700 px-4 py-2.5 text-sm font-black text-white">{saving?"Saving...":"Save Payment"}</button><button onClick={()=>setFeeForm({...feeForm,feeId:""})} className="rounded-xl border border-slate-200 px-4 py-2.5 text-sm font-bold">Cancel</button></div></div>}</ProfileSection>

        <ProfileSection title="Documents" icon={<FiFileText/>}><div className="grid gap-4 md:grid-cols-2">{photoUrl&&<a target="_blank" rel="noreferrer" href={photoUrl} className="rounded-2xl border border-slate-200 p-4 hover:border-green-300 hover:bg-green-50"><div className="flex items-center justify-between"><div><p className="text-xs font-black uppercase text-slate-500">Student Photo</p><p className="mt-1 font-bold">View / Download</p></div><FiDownload className="text-green-700"/></div></a>}{documentUrl&&<a target="_blank" rel="noreferrer" href={documentUrl} className="rounded-2xl border border-slate-200 p-4 hover:border-green-300 hover:bg-green-50"><div className="flex items-center justify-between"><div><p className="text-xs font-black uppercase text-slate-500">Identity Proof</p><p className="mt-1 font-bold">{student.student_document_type||messageData["Identity Proof Type"]||"Document"} · View / Download</p></div><FiDownload className="text-green-700"/></div></a>}</div>{!photoUrl&&!documentUrl&&<p className="rounded-2xl bg-slate-50 p-6 text-center text-sm text-slate-500">Admission documents available nahi hain.</p>}</ProfileSection>

        <ProfileSection title="Student ID Card" icon={<FiCreditCard/>} action={<button onClick={printIdCard} className="inline-flex items-center gap-2 rounded-xl bg-slate-900 px-4 py-2.5 text-sm font-black text-white"><FiPrinter/> Print ID Card</button>}><div className="mx-auto max-w-3xl overflow-hidden rounded-[28px] border border-green-200 bg-white shadow-xl"><div className="bg-gradient-to-r from-[#053b20] to-[#0a9145] p-6 text-white sm:p-8"><p className="text-xs font-black uppercase tracking-[0.3em] text-green-100">Madrasa Majmaul Bahrain Bijol</p><h3 className="mt-2 text-2xl font-black sm:text-3xl">Student Identity Card</h3></div><div className="grid gap-6 p-6 sm:grid-cols-[150px_1fr] sm:p-8">{photoUrl?<img src={photoUrl} alt="Student" className="mx-auto h-44 w-36 rounded-2xl border-4 border-green-100 object-cover sm:mx-0"/>:<div className="mx-auto flex h-44 w-36 items-center justify-center rounded-2xl bg-green-50 text-4xl font-black text-green-700 sm:mx-0">{initials}</div>}<div><h4 className="text-2xl font-black">{student.student_name}</h4><p className="mt-2 text-sm text-slate-500">Student ID</p><p className="font-mono text-lg font-black text-green-700">{student.student_id}</p><p className="mt-3 text-sm text-slate-500">Course</p><p className="font-bold">{student.course||"—"}</p><span className="mt-4 inline-flex rounded-full bg-green-100 px-3 py-1.5 text-xs font-black text-green-700">APPROVED STUDENT</span></div></div><div className="border-t border-slate-100 bg-green-50/50 px-6 py-4 text-xs text-slate-500 sm:px-8">Official student identification · Issued by Madrasa Administration</div></div></ProfileSection>

        <ProfileSection title="Activity History" icon={<FiActivity/>}><div className="space-y-4"><TimelineItem title="Admission record created" date={formatDate(student.created_at)} description="Student admission application record."/><TimelineItem title="Admission approved" date={formatDate(student.approved_at)} description={student.approved_at?"Student profile became approved.":"Approval timestamp not available."}/><TimelineItem title="Latest profile update" date={formatDate(student.updated_at)} description="Most recent student record update."/>{fees.some(f=>f.amount_paid>0)&&<TimelineItem title="Fee payments recorded" date={formatDate(fees.find(f=>f.amount_paid>0)?.payment_date)} description={`${fees.filter(f=>f.amount_paid>0).length} payment month(s) recorded.`}/>} {exams.length>0&&<TimelineItem title="Results recorded" date={formatDate(exams[0].exam_date)} description={`${exams.length} examination result record(s).`}/>}</div></ProfileSection>
      </div>
    </section>
  </main>;
}

function StatCard({icon,label,value}:{icon:React.ReactNode;label:string;value:string}){return <div className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-center justify-between"><p className="text-xs font-black uppercase tracking-wider text-slate-500">{label}</p><span className="rounded-xl bg-green-50 p-2.5 text-green-700">{icon}</span></div><p className="mt-3 break-words text-xl font-black text-slate-900">{value}</p></div>}
function ProfileSection({title,icon,action,children}:{title:string;icon:React.ReactNode;action?:React.ReactNode;children:React.ReactNode}){return <section className="overflow-hidden rounded-3xl border border-slate-200 bg-white shadow-sm"><div className="flex items-center justify-between gap-4 border-b border-slate-100 px-5 py-5 sm:px-7"><div className="flex items-center gap-3"><span className="rounded-xl bg-green-50 p-2.5 text-green-700">{icon}</span><h2 className="text-xl font-black text-slate-900">{title}</h2></div>{action}</div><div className="p-5 sm:p-7">{children}</div></section>}
function InfoGrid({items}:{items:[string,string][]}){return <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{items.map(([label,value])=><div key={label} className="rounded-2xl border border-slate-100 bg-slate-50/70 p-4"><p className="text-[10px] font-black uppercase tracking-wider text-slate-400">{label}</p><p className="mt-2 break-words text-sm font-extrabold text-slate-800">{value||"—"}</p></div>)}</div>}
function MiniStat({label,value,tone}:{label:string;value:string|number;tone:"green"|"red"|"amber"|"blue"}){const classes={green:"bg-green-50 text-green-700",red:"bg-red-50 text-red-700",amber:"bg-amber-50 text-amber-700",blue:"bg-blue-50 text-blue-700"}[tone];return <div className={`rounded-2xl p-4 ${classes}`}><p className="text-xs font-black uppercase tracking-wider opacity-80">{label}</p><p className="mt-1 text-xl font-black">{value}</p></div>}
function TimelineItem({title,date,description}:{title:string;date:string;description:string}){return <div className="relative flex gap-4"><div className="mt-1 h-3 w-3 shrink-0 rounded-full bg-green-600 ring-4 ring-green-50"/><div><p className="font-black">{title}</p><p className="mt-0.5 text-xs font-bold text-green-700">{date}</p><p className="mt-1 text-sm text-slate-500">{description}</p></div></div>}
